<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $listings = get_posts( array( 'post_type' => 'oglas', 'post_status' => array( 'publish', 'pending', 'draft', 'reject' ), 'author' => get_current_user_id(), 'numberposts' => -1 ) ); $labels = array( 'publish' => 'Objavljen', 'pending' => 'Čeka odobrenje', 'draft' => 'Nacrt', 'reject' => 'Odbijen' ); ?>
<section class="nekoko-dashboard"><h2>Moji oglasi</h2><?php echo nekoko_core_dashboard_nav(); ?><?php if ( isset( $_GET['oglas_postavljen'] ) ) { echo nekoko_core_form_notice( get_transient( 'nekoko_listing_success_' . get_current_user_id() ) ?: 'Oglas je uspešno sačuvan.' ); delete_transient( 'nekoko_listing_success_' . get_current_user_id() ); } ?><div class="nekoko-listings"><?php foreach ( $listings as $listing ) { $categories = nekoko_core_oglas_categories( $listing->ID ); ?><article class="nekoko-listing-card"><?php if ( has_post_thumbnail( $listing ) ) { echo get_the_post_thumbnail( $listing, 'medium' ); } ?><h3><?php echo esc_html( $listing->post_title ); ?></h3><p>Tip: <?php $type = nekoko_core_oglas_classification( $listing->ID ); echo esc_html( is_array( $type ) ? $type['root']->name : '—' ); ?></p><p>Kategorija: <?php echo esc_html( $categories ? $categories[0]->name : '—' ); ?></p><p><?php echo esc_html( get_the_date( '', $listing ) ); ?> · <?php echo esc_html( $labels[ $listing->post_status ] ?? $listing->post_status ); ?></p><?php if ( 'publish' === $listing->post_status ) { ?><a href="<?php echo esc_url( get_permalink( $listing ) ); ?>">Pogledajte</a><?php } ?> <a href="<?php echo esc_url( add_query_arg( 'oglas_id', $listing->ID, nekoko_core_page_url( 'postavite-oglas' ) ) ); ?>">Izmenite</a> <a data-nekoko-confirm="Da li želite da premestite oglas u otpad?" href="<?php echo esc_url( wp_nonce_url( add_query_arg( 'nekoko_delete_listing', $listing->ID, nekoko_core_page_url( 'moji-oglasi' ) ), 'nekoko_delete_listing_' . $listing->ID ) ); ?>">Obrišite</a></article><?php } if ( ! $listings ) { ?><p>Još nemate oglase.</p><?php } ?></div></section>
